use allowit::prelude::*;
pub fn execute(ctx: &AllowitContext) -> allowit::Result {
    let vendors: Vec<Address> = allowit::param(ctx, "vendors");
    for vendor in &vendors {
        if *vendor == ctx.request.recipient {
            return Ok(());
        }
    }
    Ok(())
}
